package br.com.rotas.controller;
import br.com.rotas.config.AppProperties;import br.com.rotas.domain.*;import br.com.rotas.integration.*;import br.com.rotas.service.*;import com.fasterxml.jackson.databind.ObjectMapper;import org.junit.jupiter.api.*;import org.springframework.test.web.servlet.*;import org.springframework.test.web.servlet.setup.MockMvcBuilders;import java.util.List;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
class ControllerTest {
  MockMvc mvc;
  @BeforeEach void setup(){AppProperties p=props();ObjectMapper om=new ObjectMapper();RoutingService routing=new RoutingService(p,om){@Override public RouteData route(Point a,Point b,double km){return new RouteData(km,100,List.of(),true);}};GraphService graphs=new GraphService(om,routing,p);GeocodingService geo=new GeocodingService(p,om){@Override public List<GeocodingResult> search(String q){return result();}@Override public List<GeocodingResult> searchBroad(String q){return result();}private List<GeocodingResult> result(){return List.of(new GeocodingResult("Rua A","Rua A","1","Saúde","São Paulo","SP","04000",-23.61,-46.64,false));}};var route=new RouteOptimizationService(graphs,new DijkstraService());mvc=MockMvcBuilders.standaloneSetup(new GraphController(graphs,p),new GeocodingController(geo),new RouteController(route)).setControllerAdvice(new GlobalExceptionHandler()).build();}
  AppProperties props(){return new AppProperties(new AppProperties.Store("STORE","Loja","End",-23.61562,-46.63918),new AppProperties.Region(-23.72,-23.55,-46.75,-46.58,"x",List.of()),new AppProperties.External(new AppProperties.External.Nominatim("http://test","test",1,0),new AppProperties.External.Osrm("http://test",1),new AppProperties.External.Overpass("http://test",1)),true,AppProperties.GraphGeneration.defaults());}
  @Test void graphEndpointReturnsMatrix()throws Exception{mvc.perform(get("/api/graph")).andExpect(status().isOk()).andExpect(jsonPath("$.matrix").isArray()).andExpect(jsonPath("$.graph.points[0].type").value("STORE"));}
  @Test void geocodingEndpointReturnsNormalizedResults()throws Exception{mvc.perform(get("/api/geocoding/search").param("query","Rua A")).andExpect(status().isOk()).andExpect(jsonPath("$[0].road").value("Rua A"));}
  @Test void geocodingEndpointAcceptsBroadOriginScope()throws Exception{mvc.perform(get("/api/geocoding/search").param("query","Rua A").param("scope","origin")).andExpect(status().isOk()).andExpect(jsonPath("$[0].displayName").value("Rua A"));}
  @Test void invalidRouteRequestHasConsistentError()throws Exception{mvc.perform(post("/api/routes/optimize").contentType("application/json").content("{\"name\":\"\",\"address\":\"\",\"latitude\":0,\"longitude\":0}")).andExpect(status().isBadRequest()).andExpect(jsonPath("$.code").value("INVALID_INPUT"));}
}
